const globalVariable = "I am global";

function myFunction() {
  const functionVariable = "I am in function scope";
  if (true) {
    const blockVariable = "I am block scoped";
    var leaky = "var ignores blocks";
    console.log(globalVariable, "|", functionVariable, "|", blockVariable);
  }
  console.log(leaky);
  try {
    console.log(blockVariable);
  } catch (e) {
    console.log("blockVariable ->", e.name);
  }
}
myFunction();

const name = "global";
function outer() {
  const name = "outer";
  return function inner() { return name; };
}
console.log(outer()());

console.log(a);            // undefined (var hoisted)
var a = 10;

console.log(sayHi());      // works - declaration hoisted
function sayHi() { return "hi from hoisted function"; }

try {
  console.log(b);
} catch (e) {
  console.log("let b ->", e.name, "-", e.message);
}
let b = 5;

try {
  expr();
} catch (e) {
  console.log("var expr ->", e.name);
}
var expr = function () {};

var v = 1;
function test() {
  console.log(v);          // undefined - local v is hoisted
  var v = 2;
}
test();

function makeCounter() {
  let count = 0;
  return {
    increment: () => ++count,
    decrement: () => --count,
    get value() { return count; },
  };
}
const c1 = makeCounter(), c2 = makeCounter();
c1.increment(); c1.increment(); c2.increment();
console.log(c1.value, c2.value, c1.count);

function multiplier(factor) {
  return (number) => number * factor;
}
const double = multiplier(2);
console.log(double(5), multiplier(10)(5));

function once(fn) {
  let done = false, result;
  return (...args) => (done ? result : ((done = true), (result = fn(...args))));
}
const init = once(() => { console.log("initialising..."); return 42; });
console.log(init(), init());

const withVar = [];
for (var i = 0; i < 3; i++) withVar.push(() => i);
console.log(withVar.map((f) => f()));      // [3, 3, 3]

const withLet = [];
for (let j = 0; j < 3; j++) withLet.push(() => j);
console.log(withLet.map((f) => f()));      // [0, 1, 2]

const withIife = [];
for (var k = 0; k < 3; k++) withIife.push(((n) => () => n)(k));
console.log(withIife.map((f) => f()));     // [0, 1, 2]

(function () {
  "use strict";
  const obj = {
    name: "Kodyfier",
    regular() { return this && this.name; },
    delayed() {
      return [1].map(() => this.name);        // arrow keeps obj as this
    },
  };
  console.log(obj.regular());
  const detached = obj.regular;
  console.log(detached());                     // undefined in strict mode
  console.log(obj.delayed());

  function Person(name) { this.name = name; }
  console.log(new Person("Ravi").name);
  console.log(detached.call({ name: "borrowed" }));
})();

const bioData = {
  name: "Thapa Technical",
  age: 30,
  greet() {
    console.log(`Hi, I'm ${this.name}. I'm ${this.age} years old.`);
  },
};
const student = { name: "vinod", age: 29 };

bioData.greet();
bioData.greet.call(student);
bioData.greet.apply(student);
const bound = bioData.greet.bind(student);
bound();

function intro(greeting, punct) {
  return `${greeting}, ${this.name}${punct}`;
}
console.log(intro.call(student, "Hello", "!"));
console.log(intro.apply(student, ["Hey", "?"]));

const multiply = (a, b) => a * b;
const double = multiply.bind(null, 2);
console.log(double(21));
